/* a hand is ROUNDS pairs drawn at random from every pair the window can make; 'Try another set' reloads and deals another */
var PAIRS=(function(){ var b=ALL.slice(), k, j, t; for(k=b.length-1;k>0;k--){ j=Math.floor(Math.random()*(k+1)); t=b[k]; b[k]=b[j]; b[j]=t; } return b.slice(0,ROUNDS); })();
var stage=document.getElementById('stage'), score=document.getElementById('score'), fin=document.getElementById('final'), main=document.getElementById('main');
var esc=function(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');};
/* the reveal shows the tally and the date, never a name (SPEC 2.11) */
function reveal(o){
  var h='<span class="tag">'+(o.fight?'Had a no vote':'No one voted no')+'</span><b class="num">'+o.ay+'–'+o.no+'</b> on <span class="nw">'+esc(o.dl)+'</span>';
  h+='<div class="rlinks"><a class="pl-pill" href="decisions.html?open='+encodeURIComponent(o.id)+'">See the full record</a>'+(o.src?'<a class="pl-pill" href="'+esc(o.src)+'" target="_blank" rel="noopener">Minutes (PDF)</a>':'')+'</div>';
  return h;
}
function card(o,key,n){
  return '<div class="card '+(o.fight?'isfight':'quiet')+'" data-k="'+key+'">'+
    '<button class="pick" type="button"><span class="cn" aria-hidden="true">'+n+'</span><span class="t">'+esc(o.t)+'</span></button>'+
    '<div class="rv" hidden>'+reveal(o)+'</div></div>';
}
function scoreText(){ return 'Question '+(i+1)+' of '+PAIRS.length+' · '+right+' correct'; }
function paint(){
  locked=false; main.classList.remove('docked');
  score.textContent=scoreText();
  var p=PAIRS[i];
  stage.innerHTML='<p class="qq" id="yrl"><span class="num">'+p.y+'</span>: which of these had a no vote?</p><p class="rnote">Titles as printed by the county, a missing space put back</p>'+
    '<div role="group" aria-labelledby="yrl">'+card(p.a,'a',1)+card(p.b,'b',2)+'</div>'+
    '<div class="dock" id="dock" hidden><div class="verdict" id="v" role="status" aria-live="polite"></div>'+
    '<button class="pl-btn pri" id="n" type="button">'+(i+1<PAIRS.length?'Next question':'See the result')+'</button></div>';
  [].forEach.call(stage.querySelectorAll('.card'),function(c){c.querySelector('.pick').addEventListener('click',function(){pick(c);});});
  document.getElementById('n').addEventListener('click',next);
}
function pick(c){
  if(locked) return; locked=true;
  var p=PAIRS[i], chose=p[c.getAttribute('data-k')];
  [].forEach.call(stage.querySelectorAll('.card'),function(x){
    x.querySelector('.pick').disabled=true; x.classList.add('show'); x.querySelector('.rv').hidden=false;});
  c.classList.add('chosen');
  var dock=document.getElementById('dock'), v=document.getElementById('v');
  dock.hidden=false; main.classList.add('docked');
  if(chose.fight){right++;v.textContent='Correct: that one had a no vote.';}
  else{v.textContent='Not correct: the other one had the no vote.';}
  score.textContent=scoreText();
  var n=document.getElementById('n'); n.focus({preventScroll:true});
}
function next(){ i++; if(i<PAIRS.length){paint();var s=document.querySelector('.card .pick');if(s)s.focus();window.scrollTo(0,0);} else finish(); }
function finish(){
  stage.innerHTML=''; score.textContent=''; main.classList.remove('docked');
  fin.innerHTML='<p class="big num">'+right+' / '+PAIRS.length+'</p>'+
    '<p class="fnote"><b>'+right+' of '+PAIRS.length+' answered correctly.</b> Of the '+N_VOTE+' votes read, '+N_NO+' had a no vote ('+NO_PCT+'%); '+
    N_BUD+' of those mention a budget or a tax in the title. Every vote in this quiz is real: <a href="decisions.html">the full register</a> lists them all.</p>'+
    '<button class="pl-btn" type="button" onclick="location.reload()">Try another set</button>';
  fin.hidden=false; fin.querySelector('.big').setAttribute('tabindex','-1'); fin.querySelector('.big').focus();
}
document.addEventListener('keydown',function(e){
  if(e.ctrlKey||e.metaKey||e.altKey) return;
  if(!fin.hidden) return;
  if((e.key==='1'||e.key==='2')&&!locked){var c=stage.querySelectorAll('.card')[+e.key-1]; if(c){e.preventDefault();pick(c);}}
  else if((e.key==='n'||e.key==='N')&&locked){e.preventDefault();next();}
});
paint();
